\version "2.27.2"
% automatically converted by musicxml2ly from 31f-Direction-Multiline-Compounds.xml
\pointAndClickOff

%% additional macros required by the score:
"p text
in
a small box" =
#(make-dynamic-script #{
  \markup {
    \normal-text \concat { \dynamic p \fontsize #-0.579 " " \box \concat { \fontsize #-0.579 \center-column { text in "a small box" } } }
  }
#})

\header {
  texidoc = "A test that checks how newlines in <words> elements are supported.

    Within a single <direction> element to be placed above the staff, the ‘p’
    dynamic symbol gets followed by a single space, which in turn is followed by
    some boxed text that spreads over three lines and has the attribute
    ‘valign=\"center\"’. The latter two also set the attribute
    ‘xml:space=\"preserve\"’."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c' {
  \clef "treble" \time 4/4 \key c \major c1 ^\"p text
in
a small box" \bar "|."
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
  % To create MIDI output, uncomment the following line:
  % \midi { \tempo 4 = 100 }
}
